SELECT 

FROM risk_assessment
WHERE 1=1

    AND project_id = #{param.projectId}


    AND counterpart_id = #{param.counterpartId}


    AND assessment_no LIKE CONCAT('%', #{param.assessmentNo}, '%')


    AND assessment_name LIKE CONCAT('%', #{param.assessmentName}, '%')


    AND assessment_type = #{param.assessmentType}


    AND assessor_id = #{param.assessorId}



    AND assessment_status = #{param.assessmentStatus}


    AND approval_status = #{param.approvalStatus}


    AND approver_id = #{param.approverId}


    AND risk_level = #{param.riskLevel}


    AND total_score >= #{param.minTotalScore}


    AND total_score <= #{param.maxTotalScore}


    AND assessment_date >= #{param.assessmentStartDate}


    AND assessment_date <= #{param.assessmentEndDate}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}


    AND create_by = #{param.createBy}


    AND (assessment_no LIKE CONCAT('%', #{param.keyword}, '%')
         OR assessment_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR remarks LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY create_time DESC, id DESC

SELECT COUNT(1) > 0
FROM risk_assessment
WHERE assessment_no = #{assessmentNo}

    AND id != #{excludeId}

