mapper.select:
SELECT COUNT(*) as totalCount, COUNT(CASE WHEN assessment_status = 1 THEN 1 END) as pendingCount, COUNT(CASE WHEN assessment_status = 2 THEN 1 END) as inProgressCount, COUNT(CASE WHEN assessment_status = 3 THEN 1 END) as completedCount, COUNT(CASE WHEN approval_status = 1 THEN 1 END) as pendingApprovalCount, COUNT(CASE WHEN approval_status = 2 THEN 1 END) as approvedCount, COUNT(CASE WHEN approval_status = 3 THEN 1 END) as rejectedCount, COUNT(CASE WHEN risk_level >= 4 THEN 1 END) as highRiskCount, AVG(total_score) as avgScore FROM risk_assessment WHERE 1=1
AND project_id = #{param.projectId}
AND assessment_date >= #{param.assessmentStartDate}
AND assessment_date <= #{param.assessmentEndDate}

SELECT risk_level as riskLevel, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM risk_assessment WHERE 1=1 AND project_id = #{param.projectId} ), 2) as percentage FROM risk_assessment WHERE 1=1
AND project_id = #{param.projectId}
GROUP BY risk_level ORDER BY risk_level

SELECT assessment_status as assessmentStatus, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM risk_assessment WHERE 1=1 AND project_id = #{param.projectId} ), 2) as percentage FROM risk_assessment WHERE 1=1
AND project_id = #{param.projectId}
GROUP BY assessment_status ORDER BY assessment_status

SELECT DATE_FORMAT(assessment_date, '%Y-%m') as month, COUNT(*) as count, COUNT(CASE WHEN risk_level >= 4 THEN 1 END) as highRiskCount, AVG(total_score) as avgScore FROM risk_assessment WHERE assessment_date >= DATE_SUB(SYSDATE, INTERVAL 12 MONTH)
AND project_id = #{param.projectId}
GROUP BY DATE_FORMAT(assessment_date, '%Y-%m') ORDER BY month

SELECT

FROM risk_assessment
WHERE risk_level >= 3

    AND project_id = #{param.projectId}


    AND assessment_name LIKE '%' || #{param.assessmentName} || '%'


    AND risk_level = #{param.riskLevel}


    AND assessment_status = #{param.warningStatus}


    AND assessment_date >= #{param.startDate}


    AND assessment_date <= #{param.endDate}

ORDER BY risk_level DESC, total_score DESC, create_time DESC

SELECT COUNT(*)
FROM risk_assessment
WHERE risk_level = #{riskLevel}

SELECT COUNT(*)
FROM risk_assessment
WHERE assessment_type = #{assessmentType}
